package model

// Record is the persisted shape shared across the Go backend, the TypeScript
// client (client.ts), and the service config (config.yaml). Its ArchivedID field
// is serialized as the JSON key `archived_id`.
type Record struct {
	ArchivedID string `json:"archived_id"`
	Name       string `json:"name"`
}

// Record mirrors the Go `model.Record` struct. The `archivedId` field is the
// camelCase form of the `archived_id` JSON key produced by the backend.
export interface Record {
  archivedId: string;
  name: string;
}
